	["GUIDE_ADVISOR_ROGUE_OUTLAW_10_ROT_1"] = "Öffne dich wenn möglich aus dem Stealth-Modus (Hinterhalt) und halte den Druck mit Sinister Strike aufrecht.",
	["GUIDE_ADVISOR_ROGUE_OUTLAW_10_ROT_2"] = "Geben Sie Combo-Punkte frühzeitig mit Slice and Dice aus, um die Verfügbarkeit beim Leveln aufrechtzuerhalten.",
	["GUIDE_ADVISOR_ROGUE_OUTLAW_10_ROT_3"] = "Verwenden Sie Dispatch, wann immer Sie über genügend Combo-Punkte für ein sauberes Finisher-Fenster verfügen.",
	["GUIDE_ADVISOR_ROGUE_OUTLAW_10_DEF_1"] = "Verwenden Sie Crimson Vial proaktiv zwischen den Zügen, damit Sie in Bewegung bleiben.",
	["GUIDE_ADVISOR_ROGUE_OUTLAW_10_DEF_2"] = "Verwenden Sie Finte bei schweren AoE-Paketen und Dungeon-Mechaniken.",
	["GUIDE_ADVISOR_ROGUE_OUTLAW_10_DEF_3"] = "Führen Sie gefährliche Würfe frühzeitig aus; Dies verhindert mehr Schäden als eine späte Heilung.",
	["GUIDE_ADVISOR_ROGUE_OUTLAW_10_TAL_1"] = "Priorisieren Sie zuerst Talente, die den Energiefluss und die Generierung von Combo-Punkten glätten.",
	["GUIDE_ADVISOR_ROGUE_OUTLAW_10_TAL_2"] = "Nehmen Sie Bewegungs-/Nutzungsknoten frühzeitig in Anspruch, wenn sie die Ausfallzeit zwischen den Zugvorgängen verkürzen.",
	["GUIDE_ADVISOR_ROGUE_OUTLAW_30_ROT_1"] = "Behalten Sie Slice and Dice mit minimalen Aktualisierungen bei; Vermeiden Sie eine Überbelegung der Combo-Punkte.",
	["GUIDE_ADVISOR_ROGUE_OUTLAW_30_ROT_2"] = "Verwenden Sie „Zwischen den Augen“ während kontrollierter Burst-Fenster und sorgen Sie für eine hohe Nahkampfverfügbarkeit.",
	["GUIDE_ADVISOR_ROGUE_OUTLAW_30_ROT_3"] = "Verwenden Sie „Klingenwirbel“, wenn Sie mehr als zwei nahe beieinander liegende Ziele bekämpfen.",
	["GUIDE_ADVISOR_ROGUE_OUTLAW_30_DEF_1"] = "Verwenden Sie Evasion für körperlich schwere Züge. Bei Bedarf mit Kiten kombinieren.",
	["GUIDE_ADVISOR_ROGUE_OUTLAW_30_DEF_2"] = "Cloak of Shadows ist für magischen Druck oder gefährliche Zaubererpakete gedacht.",
	["GUIDE_ADVISOR_ROGUE_OUTLAW_30_TAL_1"] = "Bevorzugen Sie Talente, die die Spaltkonsistenz für Level-/Dive-Pakete verbessern.",
	["GUIDE_ADVISOR_ROGUE_OUTLAW_30_TAL_2"] = "Vermeiden Sie es, zu früh zu viel in Nischen-Einzelzielknoten zu investieren.",
	["GUIDE_ADVISOR_ROGUE_OUTLAW_60_ROT_1"] = "Bauen Sie auf eine anhaltende Zuggeschwindigkeit auf: Gehen Sie schnell in den Kampf und halten Sie die Abklingzeit niedrig.",
	["GUIDE_ADVISOR_ROGUE_OUTLAW_60_ROT_2"] = "Setzen Sie Adrenaline Rush aggressiv bei großen Zügen ein, um beim Questen ein hohes Tempo aufrechtzuerhalten.",
	["GUIDE_ADVISOR_ROGUE_OUTLAW_60_ROT_3"] = "Halten Sie Blade Flurry auf Multi-Ziel-Pakete ausgerichtet, anstatt es zufällig zu verwenden.",
	["GUIDE_ADVISOR_ROGUE_OUTLAW_60_DEF_1"] = "Rotieren Sie Finte, Crimson Vial und Klassenverteidigungen, anstatt sie alle auf einmal zu stapeln.",
	["GUIDE_ADVISOR_ROGUE_OUTLAW_60_DEF_2"] = "Verwenden Sie Kontrollwerkzeuge (Blind-/Nierenschuss), um den eingehenden Schaden bei gefährlichen Mobs zu reduzieren.",
	["GUIDE_ADVISOR_ROGUE_OUTLAW_60_TAL_1"] = "Wählen Sie Talente aus, die Ausfallzeiten reduzieren und den nachhaltigen Spaltwert verbessern.",
	["GUIDE_ADVISOR_ROGUE_OUTLAW_60_TAL_2"] = "Nehmen Sie Überlebenstalente, wenn die Zuggröße schneller zunimmt als die Qualität Ihrer Ausrüstung.",
	["GUIDE_ADVISOR_ROGUE_OUTLAW_80_ROT_1"] = "Verfeinern Sie die Finisher-Trittfrequenz: Vermeiden Sie eine Überschreitung der Energie- und Combopunkte, bevor Fenster platzen.",
	["GUIDE_ADVISOR_ROGUE_OUTLAW_80_ROT_2"] = "Nutzen Sie Abklingzeiten bei der Pull-Trittfrequenz, anstatt zu lange für perfekte Momente zu sparen.",
	["GUIDE_ADVISOR_ROGUE_OUTLAW_80_DEF_1"] = "Planen Sie für jeden gefährlichen Zug eine Verteidigung ein, anstatt zu spät zu reagieren.",
	["GUIDE_ADVISOR_ROGUE_OUTLAW_80_DEF_2"] = "Verwenden Sie Cloak/Evasion als Skript-Antwort auf bekannte Pack-Bedrohungen.",
	["GUIDE_ADVISOR_ROGUE_OUTLAW_80_TAL_1"] = "Wechseln Sie zu Ihrem bevorzugten, endspielorientierten Talentpfad, während Sie Level 90 erreichen.",
	["GUIDE_ADVISOR_ROGUE_OUTLAW_80_TAL_2"] = "Behalten Sie Utility-Knoten bei, die die Open-World- und Delve-Konsistenz direkt verbessern.",
	["GUIDE_ADVISOR_PALADIN_PROTECTION_10_ROT_1"] = "Halten Sie die Weihe während des Kampfes, wann immer möglich, unter Ihren Füßen aktiv.",
	["GUIDE_ADVISOR_PALADIN_PROTECTION_10_ROT_2"] = "Benutzen Sie „Urteil“ und „Schild des Rächers“ in der Abklingzeit für Bedrohung und den Fluss heiliger Kraft.",
	["GUIDE_ADVISOR_PALADIN_PROTECTION_10_ROT_3"] = "Gib heilige Kraft für den Schild der Rechtschaffenen aus, um die Verfügbarkeit von Schaden und Schadensminderung zu erhöhen.",
	["GUIDE_ADVISOR_PALADIN_PROTECTION_10_DEF_1"] = "Setzen Sie Ardent Defender frühzeitig bei gefährlichen Zügen ein, anstatt zu lange zu warten.",
	["GUIDE_ADVISOR_PALADIN_PROTECTION_10_DEF_2"] = "Nutzen Sie Word of Glory als Notfallstabilisator, wenn die Gesundheit schnell nachlässt.",
	["GUIDE_ADVISOR_PALADIN_PROTECTION_10_DEF_3"] = "Verwenden Sie häufig Unterbrechungs-/Betäubungswerkzeuge, um eingehenden Schaden durch den Zauberer zu verhindern.",
	["GUIDE_ADVISOR_PALADIN_PROTECTION_10_TAL_1"] = "Priorisieren Sie Talente, die die Erzeugung heiliger Kraft und die Verfügbarkeit von Schilden steigern.",
	["GUIDE_ADVISOR_PALADIN_PROTECTION_10_TAL_2"] = "Nutzen Sie Bewegungs-/Nutzungsoptionen, die die Ausfallzeiten zwischen den Zügen reduzieren.",
	["GUIDE_ADVISOR_PALADIN_PROTECTION_30_ROT_1"] = "Halten Sie die Verfügbarkeit der Weihe hoch, während Sie Schild und Urteil des Rächers rotieren.",
	["GUIDE_ADVISOR_PALADIN_PROTECTION_30_ROT_2"] = "Verwenden Sie die Optionen „Gesegneter Hammer“/Hammer, um die Erzeugung heiliger Kraft in Rudeln zu verbessern.",
	["GUIDE_ADVISOR_PALADIN_PROTECTION_30_ROT_3"] = "Nutze beim Leveln häufig Abklingzeiten, anstatt sie für perfekte Momente zu speichern.",
	["GUIDE_ADVISOR_PALADIN_PROTECTION_30_DEF_1"] = "Rotieren Sie die Defensive je nach Pull-Größe: Kleine Defensive zuerst, große Defensive bei Spike Pulls.",
	["GUIDE_ADVISOR_PALADIN_PROTECTION_30_DEF_2"] = "Nutzen Sie Segenswerkzeuge proaktiv für Mechaniker und gefährliche Elite-Momente.",
	["GUIDE_ADVISOR_PALADIN_PROTECTION_30_TAL_1"] = "Bevorzugen Sie Talente, die die Rudelkontrolle und die dauerhafte Zugsicherheit verbessern.",
	["GUIDE_ADVISOR_PALADIN_PROTECTION_30_TAL_2"] = "Behalten Sie genügend Verteidigungsknoten bei, solange Ausrüstung und Statistiken noch inkonsistent sind.",
	["GUIDE_ADVISOR_PALADIN_PROTECTION_60_ROT_1"] = "Die Plankette bewegt sich um die Platzierung der Weihe herum und der Fernkampfschild springt zurück.",
	["GUIDE_ADVISOR_PALADIN_PROTECTION_60_ROT_2"] = "Halten Sie die Betriebszeit von „Schild der Rechtschaffenen“ stabil, bevor Sie mit größeren Zügen beginnen.",
	["GUIDE_ADVISOR_PALADIN_PROTECTION_60_ROT_3"] = "Verwenden Sie Burst-Fenster bei Paketen mit mehreren Zielen, um das Leveltempo hoch zu halten.",
	["GUIDE_ADVISOR_PALADIN_PROTECTION_60_DEF_1"] = "Verwenden Sie „Eifernder Verteidiger/Wächter der alten Könige“ als geplante Abklingzeit-Antworten.",
	["GUIDE_ADVISOR_PALADIN_PROTECTION_60_DEF_2"] = "Nutzen Sie die Selbstheilung zwischen den Zügen, um mit Schwung in den nächsten Kampf zu gehen.",
	["GUIDE_ADVISOR_PALADIN_PROTECTION_60_TAL_1"] = "Wählen Sie Talente aus, die die nachhaltige Schadensbegrenzung und den zuverlässigen AoE-Durchsatz verbessern.",
	["GUIDE_ADVISOR_PALADIN_PROTECTION_60_TAL_2"] = "Füge Utility-Talente hinzu, die die Kontrolle des Delve-Mülls und die Handhabung der Zauberer vereinfachen.",
	["GUIDE_ADVISOR_PALADIN_PROTECTION_80_ROT_1"] = "Verfeinern Sie die Kadenz der Heiligen Macht, um eine Überschreitung vor defensiven Ausgabenfenstern zu vermeiden.",
	["GUIDE_ADVISOR_PALADIN_PROTECTION_80_ROT_2"] = "Richten Sie die Abklingzeiten der Offensive an einem langen Pull-Timing statt an einzelnen Mobs aus.",
	["GUIDE_ADVISOR_PALADIN_PROTECTION_80_DEF_1"] = "Abklingreihenfolge pro Zug im Voraus planen; Vermeiden Sie es, jede Verteidigung auf einmal zu stapeln.",
	["GUIDE_ADVISOR_PALADIN_PROTECTION_80_DEF_2"] = "Halten Sie eine wichtige Abwehrmaßnahme für unvorhergesehene Gefahren beim Kettenziehen.",
	["GUIDE_ADVISOR_PALADIN_PROTECTION_80_TAL_1"] = "Wechseln Sie zu Ihrem bevorzugten Endgame-Schutz-Setup und behalten Sie gleichzeitig den Komfort beim Leveln bei.",
	["GUIDE_ADVISOR_PALADIN_PROTECTION_80_TAL_2"] = "Behalten Sie praktische Versorgungsknoten für das Routing in der offenen Welt und im Delve bei.",
	["GUIDE_ADVISOR_WARLOCK_AFFLICTION_10_ROT_1"] = "Wenden Sie Ihre Kern-DoTs an und halten Sie sie aufrecht, bevor Sie Seelensplitter ausgeben.",
	["GUIDE_ADVISOR_WARLOCK_AFFLICTION_10_ROT_2"] = "Verwenden Sie Füllgüsse, um den Druck aufrechtzuerhalten, während Sie auf die Scherbenausgabefenster warten.",
	["GUIDE_ADVISOR_WARLOCK_AFFLICTION_10_ROT_3"] = "Geben Sie Scherben regelmäßig aus. Vermeiden Sie eine Obergrenze, solange die angestrebte Betriebszeit hoch ist.",
	["GUIDE_ADVISOR_WARLOCK_AFFLICTION_10_DEF_1"] = "Nutze „Unendliche Entschlossenheit“, wenn der eingehende Schaden zunimmt oder Eliten dich unter Druck setzen.",
	["GUIDE_ADVISOR_WARLOCK_AFFLICTION_10_DEF_2"] = "Halten Sie Healthstone bereit und verwenden Sie es früh genug, um die Kontrolle zu behalten.",
	["GUIDE_ADVISOR_WARLOCK_AFFLICTION_10_DEF_3"] = "Verwenden Sie Angst-/Kontrollwerkzeuge, um den eingehenden Druck bei Überlastung zu reduzieren.",
	["GUIDE_ADVISOR_WARLOCK_AFFLICTION_10_TAL_1"] = "Priorisieren Sie Talente, die die DoT-Verfügbarkeit und die Shard-Wirtschaft stärken.",
	["GUIDE_ADVISOR_WARLOCK_AFFLICTION_10_TAL_2"] = "Nehmen Sie Überlebensfähigkeitsknoten frühzeitig ein, wenn die Größe des Solo-Leveling-Pulls zunimmt.",
	["GUIDE_ADVISOR_WARLOCK_AFFLICTION_30_ROT_1"] = "DoTs effizient aktualisieren; Vermeiden Sie ein zu frühes Abschneiden, es sei denn, die Bewegung erzwingt dies.",
	["GUIDE_ADVISOR_WARLOCK_AFFLICTION_30_ROT_2"] = "Setzen Sie Ihre Ausführungs-/Shard-Spender-Fenster aggressiv auf Ziele mit hoher Gesundheit ein.",
	["GUIDE_ADVISOR_WARLOCK_AFFLICTION_30_ROT_3"] = "Halten Sie das Haustier-Hilfsprogramm aktiv, um während der Bewegung erlittenen Schaden zu reduzieren.",
	["GUIDE_ADVISOR_WARLOCK_AFFLICTION_30_DEF_1"] = "Rotieren Sie die Defensive und die Massenkontrolle, anstatt alle Werkzeuge gleichzeitig zu verwenden.",
	["GUIDE_ADVISOR_WARLOCK_AFFLICTION_30_DEF_2"] = "Verwenden Sie den Health Funnel und das Pet Utility, um sich beim Kettenziehen zu stabilisieren.",
	["GUIDE_ADVISOR_WARLOCK_AFFLICTION_30_TAL_1"] = "Bevorzugen Sie Talente, die die Multi-Target-DoT-Verbreitung und die Pull-Konsistenz verbessern.",
	["GUIDE_ADVISOR_WARLOCK_AFFLICTION_30_TAL_2"] = "Halten Sie mindestens einen Verteidigungszweig aktiv, während die Ausrüstung aufholt.",
	["GUIDE_ADVISOR_WARLOCK_AFFLICTION_60_ROT_1"] = "Planen Sie die Shard-Ausgaben entsprechend der Pull-Größe: nachhaltige Ausgaben für Pakete, gezielte Ausgaben für vorrangige Ziele.",
	["GUIDE_ADVISOR_WARLOCK_AFFLICTION_60_ROT_2"] = "Halten Sie die weltweite Nutzung eng, damit die DoT-Verfügbarkeit während der Bewegung hoch bleibt.",
	["GUIDE_ADVISOR_WARLOCK_AFFLICTION_60_ROT_3"] = "Nutzen Sie häufig große Abklingzeiten, um den schnellen Levelaufstieg aufrechtzuerhalten.",
	["GUIDE_ADVISOR_WARLOCK_AFFLICTION_60_DEF_1"] = "Setzen Sie Unending Resolve proaktiv bei bekanntermaßen gefährlichen Anziehungspunkten ein.",
	["GUIDE_ADVISOR_WARLOCK_AFFLICTION_60_DEF_2"] = "Kettenkontrolleffekte, um zaubererschwere Schadensausbrüche zu verhindern.",
	["GUIDE_ADVISOR_WARLOCK_AFFLICTION_60_TAL_1"] = "Wählen Sie Talente aus, die den Shard-Fluss glätten und die Setup-Reibung zwischen den Pulls verringern.",
	["GUIDE_ADVISOR_WARLOCK_AFFLICTION_60_TAL_2"] = "Fügen Sie beim Übergang in schwierigere Gewölbe Nützlichkeits-/Überlebenstalente hinzu.",
	["GUIDE_ADVISOR_WARLOCK_AFFLICTION_80_ROT_1"] = "Verfeinern Sie die Shard-Ökonomie, um Überkapazitäten zu vermeiden und die Betriebszeit der Spender effizient zu halten.",
	["GUIDE_ADVISOR_WARLOCK_AFFLICTION_80_ROT_2"] = "Passen Sie die Abklingzeiten an dichte Pull-Fenster an, anstatt zu lange zu speichern.",
	["GUIDE_ADVISOR_WARLOCK_AFFLICTION_80_DEF_1"] = "Beginnen Sie jeden gefährlichen Zug mit einem Verteidigungs-/Kontrollplan.",
	["GUIDE_ADVISOR_WARLOCK_AFFLICTION_80_DEF_2"] = "Halten Sie Healthstone und Mobilitätstools für Notfall-Resets bereit.",
	["GUIDE_ADVISOR_WARLOCK_AFFLICTION_80_TAL_1"] = "Bewegen Sie sich auf Ihren bevorzugten Endgame-Affliction-Pfad zu und bewahren Sie dabei die Levelkonsistenz.",
	["GUIDE_ADVISOR_WARLOCK_AFFLICTION_80_TAL_2"] = "Behalten Sie wichtige Utility-Picks bei, die die Solo-Sicherheit und Zugkontrolle verbessern.",
	["GUIDE_ADVISOR_MAGE_FIRE_10_ROT_1"] = "Bauen Sie „Heating Up“ mit „Fireball“ auf und wandeln Sie es mit „Fire Blast“ in einen sofortigen „Pyroblast“ um.",
	["GUIDE_ADVISOR_MAGE_FIRE_10_ROT_2"] = "Verwenden Sie Phoenix Flames als zuverlässiges kritisches Werkzeug während Bewegungs- oder Setup-Fenstern.",
	["GUIDE_ADVISOR_MAGE_FIRE_10_ROT_3"] = "Verwenden Sie Flamestrike nur bei gestapelten Paketen. Halten Sie ansonsten den Einzelzielfluss sauber.",
	["GUIDE_ADVISOR_MAGE_FIRE_10_DEF_1"] = "Verwenden Sie Blazing Barrier, bevor Sie größere Züge ausführen, um den frühen Druck zu verringern.",
	["GUIDE_ADVISOR_MAGE_FIRE_10_DEF_2"] = "Benutzen Sie Drachenatem und Verlangsamungen, um Platz zu schaffen, anstatt ihn ins Gesicht zu tanken.",
	["GUIDE_ADVISOR_MAGE_FIRE_10_DEF_3"] = "Setzen Sie Gegenzauber proaktiv gegen gefährliche Zauberer ein, um Explosionsschaden zu verhindern.",
	["GUIDE_ADVISOR_MAGE_FIRE_10_TAL_1"] = "Priorisieren Sie Talente, die die Hot Streak-Häufigkeit und den Zauberfluss erhöhen.",
	["GUIDE_ADVISOR_MAGE_FIRE_10_TAL_2"] = "Nehmen Sie Mobilitäts-/Verteidigungsknoten frühzeitig in Anspruch, wenn sich der Zugdruck in der offenen Welt zu hoch anfühlt.",
	["GUIDE_ADVISOR_MAGE_FIRE_30_ROT_1"] = "Richten Sie die Verbrennung auf größere Gruppen oder Eliteziele aus, anstatt sie zufällig zu verwenden.",
	["GUIDE_ADVISOR_MAGE_FIRE_30_ROT_2"] = "Halten Sie die Planung von Sofortzaubern sauber: Behalten Sie Bewegungsglobale für Schadenszauber bei.",
	["GUIDE_ADVISOR_MAGE_FIRE_30_ROT_3"] = "Verwenden Sie Flamestrike in AoE-Fenstern nur, wenn Feinde lange genug in der Gruppe bleiben.",
	["GUIDE_ADVISOR_MAGE_FIRE_30_DEF_1"] = "Drehen Sie die Blazing Barrier-, Kontroll- und Kite-Werkzeuge zwischen den Zügen.",
	["GUIDE_ADVISOR_MAGE_FIRE_30_DEF_2"] = "Ice Block ist Ihr Notfall-Reset; Vermeiden Sie es, es zu spät zu verwenden.",
	["GUIDE_ADVISOR_MAGE_FIRE_30_TAL_1"] = "Bevorzugen Sie Talente, die den Verbrennungswert und die gleichmäßige Spaltung verbessern.",
	["GUIDE_ADVISOR_MAGE_FIRE_30_TAL_2"] = "Halten Sie Utility-Picks bereit, die Ausfallzeiten beim Wechseln zwischen Paketen reduzieren.",
	["GUIDE_ADVISOR_MAGE_FIRE_60_ROT_1"] = "Planen Sie die Zugkadenz entsprechend dem Wiederaufladezeitpunkt von Combustion und Phoenix Flames.",
	["GUIDE_ADVISOR_MAGE_FIRE_60_ROT_2"] = "Sorgen Sie für eine effiziente Hot Streak-Konvertierung, um Prozessverschwendung zu vermeiden.",
	["GUIDE_ADVISOR_MAGE_FIRE_60_ROT_3"] = "Benutzen Sie AoE-Burn-Fenster aggressiv in Grottentauchgängen und dichten Questpaketen.",
	["GUIDE_ADVISOR_MAGE_FIRE_60_DEF_1"] = "Betreten Sie gefährliche Bereiche mit vorbereiteter Barriere und geplantem Fluchtweg.",
	["GUIDE_ADVISOR_MAGE_FIRE_60_DEF_2"] = "Kettenkontrolle (Drachenatem/Verlangsamung/Unterbrechung), um den eingehenden Schaden zu verringern.",
	["GUIDE_ADVISOR_MAGE_FIRE_60_TAL_1"] = "Wählen Sie Talente aus, die geplatzte Fenster stabilisieren und die Reibung beim Aufbau verringern.",
	["GUIDE_ADVISOR_MAGE_FIRE_60_TAL_2"] = "Fügen Sie Überlebensknoten hinzu, wenn die Tötungsgeschwindigkeit den eingehenden Druck nicht sicher ausgleichen kann.",
	["GUIDE_ADVISOR_MAGE_FIRE_80_ROT_1"] = "Verfeinern Sie die Abklingzeit-Disziplin: Verwenden Sie „Verbrennung“ im Pull-Rhythmus, nicht bei perfekten Träumen.",
	["GUIDE_ADVISOR_MAGE_FIRE_80_ROT_2"] = "Sorgen Sie für reibungslose Ausführungs-/Bewegungsübergänge, um eine hohe Kampfverfügbarkeit zu gewährleisten.",
	["GUIDE_ADVISOR_MAGE_FIRE_80_DEF_1"] = "Beginnen Sie jeden Elitezug mit einem Verteidigungs- und Kontrollplan.",
	["GUIDE_ADVISOR_MAGE_FIRE_80_DEF_2"] = "Speichern Sie einen Notrufknopf beim Kettenziehen in risikoreichen Strecken.",
	["GUIDE_ADVISOR_MAGE_FIRE_80_TAL_1"] = "Wechseln Sie zu Ihrem bevorzugten Endgame-Fire-Build und bewahren Sie gleichzeitig die Levelstabilität.",
	["GUIDE_ADVISOR_MAGE_FIRE_80_TAL_2"] = "Behalten Sie praktische Versorgungsknoten für Grottentauchgänge und die Sicherheit in der offenen Welt bei.",
	["GUIDE_ADVISOR_WARRIOR_FURY_10_ROT_1"] = "Verwenden Sie „Blutdurst“ und „Wütender Schlag“, um Wut aufzubauen, und geben Sie sie dann mit „Rampage“ aus.",
	["GUIDE_ADVISOR_WARRIOR_FURY_10_ROT_2"] = "Halten Sie die Betriebszeit von Enrage hoch; Ihr Tempo und Ihre Überlebensfähigkeit fühlen sich besser an, wenn Sie wütend sind.",
	["GUIDE_ADVISOR_WARRIOR_FURY_10_ROT_3"] = "Benutzen Sie Whirlwind, um die Spaltung vorzubereiten, bevor Sie Ihre Heavy Hitters auf Packs drücken.",
	["GUIDE_ADVISOR_WARRIOR_FURY_10_DEF_1"] = "Setzen Sie „Enraged Regeneration“ proaktiv bei gefährlichen Zügen ein, nicht nur bei kritischen HP.",
	["GUIDE_ADVISOR_WARRIOR_FURY_10_DEF_2"] = "Setze Pummel frühzeitig ein, um Zauberausbrüche zu stoppen und den eingehenden Schaden zu reduzieren.",
	["GUIDE_ADVISOR_WARRIOR_FURY_10_DEF_3"] = "Verwenden Sie Mobilitätshilfen, um sich schnell neu zu positionieren, anstatt vermeidbare Mechaniken zu belasten.",
	["GUIDE_ADVISOR_WARRIOR_FURY_10_TAL_1"] = "Priorisieren Sie Talente, die die Wuterzeugung und die Wutkonsistenz verbessern.",
	["GUIDE_ADVISOR_WARRIOR_FURY_10_TAL_2"] = "Treffen Sie frühzeitig Utility-/Mobilitäts-Picks, wenn diese das Chain-Pull-Tempo verbessern.",
	["GUIDE_ADVISOR_WARRIOR_FURY_30_ROT_1"] = "Verbünden Sie Recklessness mit dichten Rudeln oder Elitetruppen, um stärkere Levelausbrüche zu erzielen.",
	["GUIDE_ADVISOR_WARRIOR_FURY_30_ROT_2"] = "Vermeiden Sie Rage-Overcap während Burst-Fenstern; Geben Sie aggressiv mit Rampage aus.",
	["GUIDE_ADVISOR_WARRIOR_FURY_30_ROT_3"] = "Halten Sie die Spaltvorbereitung „Whirlwind“ bei Multi-Ziel-Zügen aktiv.",
	["GUIDE_ADVISOR_WARRIOR_FURY_30_DEF_1"] = "Rotieren Sie die Defensive zwischen den Zügen, anstatt alles auf einmal zu stapeln.",
	["GUIDE_ADVISOR_WARRIOR_FURY_30_DEF_2"] = "Benutze Betäubungen/Verlangsamungen, um gefährliche Mobs zu kontrollieren, bevor sie dich kontrollieren.",
	["GUIDE_ADVISOR_WARRIOR_FURY_30_TAL_1"] = "Bevorzugen Sie Talente, die die Dauerzuggeschwindigkeit erhöhen, und nicht nur Ein-Knopf-Bursts.",
	["GUIDE_ADVISOR_WARRIOR_FURY_30_TAL_2"] = "Behalten Sie ausreichend Verteidigungswert bei, wenn Sie schwierigere Questzonen oder Höhlen betreten.",
	["GUIDE_ADVISOR_WARRIOR_FURY_60_ROT_1"] = "Planen Sie einen Pull-Rhythmus rund um Rücksichtslosigkeit und führen Sie Phasen für ein stabiles Tempo durch.",
	["GUIDE_ADVISOR_WARRIOR_FURY_60_ROT_2"] = "Halten Sie die Betriebszeit von Enrage aufrecht und vermeiden Sie gleichzeitig tote globale Konflikte zwischen Bauherren und Geldgebern.",
	["GUIDE_ADVISOR_WARRIOR_FURY_60_ROT_3"] = "Verwenden Sie das Cleave-Setup absichtlich, damit die Burst-Fenster den vollen Packwert erreichen.",
